    // Embed query (simplified - would use HF API in production)
    let embedding = embed_text(query).await?;

    // Search Qdrant
    let url = format!("{}/collections/code_chunks/points/query", qdrant_url);
    let response = client
        .post(&url)
        .json(&serde_json::json!({
            "query": embedding,
            "limit": limit,
            "with_payload": true
        }))
        .send()
        .await
        .ok();

    let mut snippets = Vec::new();
    if let Some(r) = response {
        if let Ok(json) = r.json::<serde_json::Value>().await {
            if let Some(results) = json.pointer("/result/points").and_then(|p| p.as_array()) {
                for point in results {
                    if let Some(payload) = point.pointer("/payload") {
                        snippets.push(CodeSnippet {
                            file: payload
                                .pointer("/file")
                                .and_then(|f| f.as_str())
                                .unwrap_or("")
                                .to_string(),
                            function: payload
                                .pointer("/function")
                                .and_then(|f| f.as_str())
                                .map(|s| s.to_string()),
                            language: payload
                                .pointer("/language")
                                .and_then(|l| l.as_str())
                                .unwrap_or("")
                                .to_string(),
                            code: payload
                                .pointer("/code")
                                .and_then(|c| c.as_str())
                                .unwrap_or("")
                                .to_string(),
                            similarity: point
                                .pointer("/score")
                                .and_then(|s| s.as_f64())
                                .unwrap_or(0.0),
                        });
                    }
                }
            }
        }
    }

    Ok(snippets)
}

